        Some(i) => &lower[i + "intent=".len()..],
        None => lower.as_str(),
    };
    let token: String = tail
        .trim_start()
        .chars()
        .take_while(|c| c.is_ascii_alphanumeric() || *c == '_' || *c == '-')
        .collect();

    match token.as_str() {
        "billing_question" | "billing-question" => Intent::BillingQuestion,
        "technical_support" | "technical-support" => Intent::TechnicalSupport,
        "account_change" | "account-change" => Intent::AccountChange,
        "general_inquiry" | "general-inquiry" => Intent::GeneralInquiry,
        _ => Intent::Unknown,
    }
